// SAMPLE PRODUCT DATA

const defaultProducts = [
    {
        id: 1,
        name: "Rice",
        category: "Food",
        stock: 100,
        level: 20,
        expiry: "2027-01-15",
        dailyDemand: 8
    },
    {
        id: 2,
        name: "Canned Sardines",
        category: "Canned Goods",
        stock: 15,
        level: 20,
        expiry: "2026-12-20",
        dailyDemand: 5
    },
    {
        id: 3,
        name: "Instant Noodles",
        category: "Food",
        stock: 80,
        level: 25,
        expiry: "2027-03-10",
        dailyDemand: 10
    },
    {
        id: 4,
        name: "Milk",
        category: "Dairy",
        stock: 10,
        level: 15,
        expiry: "2026-11-20",
        dailyDemand: 6
    },
    {
        id: 5,
        name: "Bottled Water",
        category: "Beverages",
        stock: 50,
        level: 15,
        expiry: "2027-06-15",
        dailyDemand: 7
    },
    {
        id: 6,
        name: "Biscuits",
        category: "Snacks",
        stock: 29,
        level: 10,
        expiry: "2026-11-08",
        dailyDemand: 4
    }
];

// LOAD SAVED DATA

let products = JSON.parse(
    localStorage.getItem("stockwiseProducts")
);

if (!Array.isArray(products)) {
    products = defaultProducts;
    saveProducts();
}

// SAVE DATA

function saveProducts() {

    localStorage.setItem(
        "stockwiseProducts",
        JSON.stringify(products)
    );

}

// FORMAT DATE

function formatDate(date) {

    if (!date) return "Not provided";

    return new Date(date + "T00:00:00")
        .toLocaleDateString();

}

// CHECK EXPIRATION

function getExpiryStatus(expiry) {

    if (!expiry) return "No expiration date";

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const expiryDate = new Date(expiry + "T00:00:00");

    const difference = Math.ceil(
        (expiryDate - today) / (1000 * 60 * 60 * 24)
    );

    if (difference < 0) {
        return "Expired";
    }

    if (difference <= 30) {
        return "Near Expiration";
    }

    return "Good";

}

// DISPLAY PRODUCTS

function displayProducts() {

    const table = document.getElementById("productRows");

    if (!table) return;

    table.innerHTML = "";

    products.forEach(product => {

        const expiryStatus = getExpiryStatus(product.expiry);

        let stockStatus = "Good";

        if (product.stock <= product.level) {
            stockStatus = "Low Stock";
        }

        let badge = "status-good";

        if (stockStatus === "Low Stock") {
            badge = "status-low";
        }

        if (expiryStatus === "Expired") {
            badge = "status-expired";
        }

        table.innerHTML += `
            <tr>

                <td class="fw-semibold">
                    ${escapeHTML(product.name)}
                </td>

                <td>
                    ${escapeHTML(product.category)}
                </td>

                <td>
                    ${product.stock}
                </td>

                <td>
                    ${product.level}
                </td>

                <td>
                    ${formatDate(product.expiry)}
                </td>

                <td>
                    <span class="badge ${badge}">
                        ${stockStatus}
                    </span>
                </td>

            </tr>
        `;

    });

}

// PREVENT HTML INJECTION IN USER-ENTERED TEXT

function escapeHTML(value) {

    return String(value).replace(/[&<>"']/g, character => {

        const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;"
        };

        return entities[character];

    });

}

// UPDATE DASHBOARD CARDS

function updateDashboard() {

    const totalProducts = products.length;

    const totalStock = products.reduce(
        (sum, product) => sum + Number(product.stock),
        0
    );

    const lowStock = products.filter(
        product => product.stock <= product.level
    ).length;

    const nearExpiry = products.filter(
        product => {
            const status = getExpiryStatus(product.expiry);

            return status === "Near Expiration" ||
                   status === "Expired";
        }
    ).length;

    document.getElementById("totalProducts").textContent =
        totalProducts;

    document.getElementById("totalStock").textContent =
        totalStock;

    document.getElementById("lowStock").textContent =
        lowStock;

    document.getElementById("nearExpiry").textContent =
        nearExpiry;

}

// ADD PRODUCT

const productForm = document.getElementById("productForm");

if (productForm) {

    productForm.addEventListener("submit", function(event) {

        event.preventDefault();

        const product = {

            id: Date.now(),

            name: document.getElementById("pName").value.trim(),

            category: document.getElementById("pCategory").value.trim(),

            stock: Number(document.getElementById("pStock").value),

            level: Number(document.getElementById("pLevel").value),

            expiry: document.getElementById("pExpiry").value,

            dailyDemand: 0

        };

        if (!product.name || !product.category) {
            alert("Please complete the product information.");
            return;
        }

        if (
            !Number.isInteger(product.stock) ||
            !Number.isInteger(product.level) ||
            product.stock < 0 ||
            product.level < 0
        ) {
            alert("Please enter valid stock and reorder values.");
            return;
        }

        products.push(product);

        saveProducts();

        refreshDashboard();

        productForm.reset();

        bootstrap.Modal.getOrCreateInstance(
            document.getElementById("addProduct")
        ).hide();

        alert("Product added successfully!");

    });

}

// POPULATE SALES DROPDOWN

function updateSalesDropdown() {

    const dropdown = document.getElementById("saleProduct");

    if (!dropdown) return;

    dropdown.innerHTML = '<option value="">Select Product</option>';

    products.forEach(product => {

        dropdown.innerHTML += `
            <option value="${product.id}">
                ${escapeHTML(product.name)}
            </option>
        `;

    });

}

// RECORD SALE

const saleForm = document.getElementById("saleForm");

if (saleForm) {

    saleForm.addEventListener("submit", function(event) {

        event.preventDefault();

        const productId = Number(
            document.getElementById("saleProduct").value
        );

        const quantity = Number(
            document.getElementById("saleQty").value
        );

        const product = products.find(
            item => item.id === productId
        );

        if (!product) {
            alert("Please select a product.");
            return;
        }

        if (
            !Number.isInteger(quantity) ||
            quantity <= 0
        ) {
            alert("Please enter a valid quantity.");
            return;
        }

        if (quantity > product.stock) {
            alert("Insufficient stock!");
            return;
        }

        product.stock -= quantity;

        saveProducts();

        refreshDashboard();

        saleForm.reset();

        alert("Sale recorded successfully!");

    });

}

// EXPIRATION MONITORING

function displayExpirationAlerts() {

    const container = document.getElementById("expiryList");

    if (!container) return;

    container.innerHTML = "";

    const alerts = products.filter(product => {

        const status = getExpiryStatus(product.expiry);

        return status === "Near Expiration" ||
               status === "Expired";

    });

    if (alerts.length === 0) {

        container.innerHTML = `
            <p class="text-muted">
                No expiration alerts at the moment.
            </p>
        `;

        return;

    }

    alerts.forEach(product => {

        const status = getExpiryStatus(product.expiry);

        const expiredClass =
            status === "Expired" ? "expired-item" : "";

        container.innerHTML += `

            <div class="alert-item ${expiredClass}">

                <div class="fw-semibold">
                    ${escapeHTML(product.name)}
                </div>

                <small class="text-muted">
                    Expiration Date: ${formatDate(product.expiry)}
                </small>

                <div class="small fw-semibold mt-1">
                    ${status}
                </div>

            </div>

        `;

    });

}

// DEMAND FORECAST

function displayForecast() {

    const container = document.getElementById("forecastList");

    if (!container) return;

    container.innerHTML = "";

    products.forEach(product => {

        const demand = Number(product.dailyDemand) || 0;

        const predictedDemand = demand * 30;

        const percentage = Math.min(
            (predictedDemand / 300) * 100,
            100
        );

        container.innerHTML += `

            <div class="forecast-item">

                <div class="d-flex justify-content-between mb-1">

                    <span class="fw-semibold">
                        ${escapeHTML(product.name)}
                    </span>

                    <span class="small text-muted">
                        ${predictedDemand} units / 30 days
                    </span>

                </div>

                <div class="forecast-bar">

                    <div class="forecast-progress"
                         style="width: ${percentage}%">
                    </div>

                </div>

            </div>

        `;

    });

}

// REORDER RECOMMENDATIONS

function displayReorderRecommendations() {

    const container = document.getElementById("reorderList");

    if (!container) return;

    container.innerHTML = "";

    const lowProducts = products.filter(
        product => product.stock <= product.level
    );

    if (lowProducts.length === 0) {

        container.innerHTML = `
            <p class="text-muted">
                All products have sufficient stock.
            </p>
        `;

        return;

    }

    lowProducts.forEach(product => {

        const recommendedQuantity = Math.max(
            0,
            Math.ceil(product.dailyDemand * 30) - product.stock
        );

        container.innerHTML += `

            <div class="d-flex justify-content-between
                        align-items-center border-bottom py-3">

                <div>

                    <div class="fw-semibold">
                        ${escapeHTML(product.name)}
                    </div>

                    <small class="text-muted">
                        Current Stock: ${product.stock}
                    </small>

                </div>

                <div class="text-end">

                    <span class="badge status-low">
                        Reorder
                    </span>

                    <div class="small fw-bold mt-1">
                        Suggested: ${recommendedQuantity} units
                    </div>

                </div>

            </div>

        `;

    });

}

// REFRESH EVERYTHING

function refreshDashboard() {

    displayProducts();

    updateDashboard();

    updateSalesDropdown();

    displayExpirationAlerts();

    displayForecast();

    displayReorderRecommendations();

}

// INITIALIZE

refreshDashboard();
